WITH rc AS (SELECT uuid, COUNT(*) n FROM rulings GROUP BY uuid),
p AS (SELECT DISTINCT fd.name jn, c.type t, c.uuid FROM cards c JOIN foreign_data fd ON fd.uuid=c.uuid AND fd.language='Japanese' WHERE c.watermark='boros')
SELECT p.jn AS japanese_name, p.t AS card_type, COALESCE(SUM(rc.n),0) AS total_rulings FROM p LEFT JOIN rc ON rc.uuid=p.uuid GROUP BY p.jn, p.t;

SELECT 'young' AS cohort, ROUND(AVG(A11)) AS avg_salary FROM district WHERE district_id IN (SELECT a.district_id FROM client c JOIN disp x ON x.client_id=c.client_id JOIN account a ON a.account_id=x.account_id WHERE c.birth_date >= '1980-01-01')
UNION ALL
SELECT 'old', ROUND(AVG(A11)) FROM district WHERE district_id IN (SELECT a.district_id FROM client c JOIN disp x ON x.client_id=c.client_id JOIN account a ON a.account_id=x.account_id WHERE c.birth_date < '1920-01-01');

WITH c AS (SELECT d.forename||' '||d.surname AS driver, r.name AS race, r.year AS year, q.q3 AS q3 FROM qualifying q JOIN drivers d ON d.driverId=q.driverId JOIN races r ON r.raceId=q.raceId
WHERE d.nationality='British' AND CAST(STRFTIME('%Y',d.dob) AS INT)>1980 AND q.q3 IS NOT NULL AND q.q3<>'')
SELECT driver, race, year, q3 FROM c WHERE q3=(SELECT MIN(q3) FROM c);

with t as (select a.district_id from loan l join account a on a.account_id=l.account_id where l.duration=24 and a.frequency='POPLATEK TYDNE' order by l.amount desc, l.loan_id limit 10),
d as (select distinct t.district_id, cast(A4 as integer) inh, A11 sal from t join district using(district_id))
select (select district_id from d order by inh desc, district_id limit 1) as most_populous_district_id, (select inh from d order by inh desc, district_id limit 1) as inhabitants, round(avg(sal),2) as avg_salary from d;

